WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.Score, p.ViewCount, COALESCE((SELECT COUNT(*) FROM Comments AS c WHERE c.PostId = p.Id), 0) AS CommentCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS rn, p.OwnerUserId FROM Posts AS p WHERE p.Score > 10), TopUsers AS (SELECT u.Id AS UserId, u.DisplayName, u.Reputation, RANK() OVER (ORDER BY u.Reputation DESC NULLS FIRST) AS UserRank FROM Users AS u WHERE NOT (u.Reputation IS NULL)) SELECT tu.DisplayName, COUNT(rp.PostId) AS PostCount, SUM(rp.ViewCount) AS TotalViews, AVG(rp.Score) AS AverageScore, GROUP_CONCAT(rp.Title, ', ') AS PostTitles, MAX(rp.CreationDate) AS LastPostDate, CASE WHEN MAX(rp.CreationDate) < CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR THEN 'Inactive' ELSE 'Active' END AS ActivityStatus FROM TopUsers AS tu LEFT JOIN RankedPosts AS rp ON tu.UserId = rp.OwnerUserId WHERE tu.UserRank <= 10 GROUP BY tu.DisplayName ORDER BY PostCount DESC NULLS FIRST